CREATE TABLE IF NOT EXISTS search_settings (id BIGINT UNSIGNED PRIMARY KEY, payload LONGTEXT NOT NULL, sealed_secrets LONGTEXT NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS search_dirty (content_id BIGINT UNSIGNED PRIMARY KEY, updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS search_pages (content_id BIGINT UNSIGNED PRIMARY KEY, kind VARCHAR(16) NOT NULL, url VARCHAR(2048) NOT NULL, fingerprint CHAR(64) NOT NULL, is_public BOOLEAN NOT NULL, was_public BOOLEAN NOT NULL DEFAULT 0, updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS search_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, engine VARCHAR(16) NOT NULL, source VARCHAR(16) NOT NULL DEFAULT 'automatic', content_id BIGINT UNSIGNED NOT NULL DEFAULT 0, url VARCHAR(2048) NOT NULL, action VARCHAR(16) NOT NULL, fingerprint CHAR(64) NOT NULL, dedup_key CHAR(64) NOT NULL, state VARCHAR(32) NOT NULL, attempts INT NOT NULL DEFAULT 0, not_before DATETIME(3) NOT NULL, lease VARCHAR(64) NOT NULL DEFAULT '', locked_until DATETIME(3) NULL, http_status INT NOT NULL DEFAULT 0, result VARCHAR(500) NOT NULL DEFAULT '', created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY search_job_dedup(dedup_key), KEY search_job_due(state,not_before), KEY search_job_content(content_id));
CREATE TABLE IF NOT EXISTS search_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, engine VARCHAR(16) NOT NULL, url VARCHAR(2048) NOT NULL, action VARCHAR(16) NOT NULL, state VARCHAR(32) NOT NULL, http_status INT NOT NULL DEFAULT 0, result VARCHAR(500) NOT NULL DEFAULT '', created_at DATETIME(3) NOT NULL, KEY search_attempt_job(job_id), KEY search_attempt_engine(engine,created_at));
CREATE TABLE IF NOT EXISTS search_quotas (engine VARCHAR(16) NOT NULL, day CHAR(10) NOT NULL, used INT NOT NULL DEFAULT 0, remote_remaining INT NOT NULL DEFAULT -1, PRIMARY KEY(engine,day));
